end

local function create_open_command(bufnr)
  local ok, cmds = pcall(api.nvim_buf_get_commands, bufnr, { builtin = false })
  if not ok then cmds = {} end
  if cmds["OpenWithSystemApplication"] then return end

  composer.verb("OpenWithSystemApplication", {
    buffer = bufnr,
    desc = "[markdown.nvim] Open image/url/file under cursor",
    routes = {
      { path = {}, run = function() require("markdown.handler").handle_cursor_action() end },
    },
  })
end

local function create_underline_headings_command(bufnr)
  if not require("markdown.config").feature_enabled("underline_headings") then return end

  local ok, cmds = pcall(api.nvim_buf_get_commands, bufnr, { builtin = false })
  if not ok then cmds = {} end
  if cmds["MarkdownNvimUnderlineHeadings"] then return end

  composer.verb("MarkdownNvimUnderlineHeadings", {
    buffer = bufnr,
    desc = "[markdown.nvim] Underline every ATX heading's text with '=' (Setext-style decoration)",
    routes = {
      {
        path = {},
        run = function()
          local cfg = require("markdown.config").get()
          local char = (cfg.underline_headings and cfg.underline_headings.char) or "="
          require("markdown.core.underline_headings").apply(bufnr, { notify = true, char = char })
        end,
      },
    },
  })
end

local function create_mdtable_commands(bufnr)
  if not require("markdown.config").feature_enabled("table_wrap") then return end

  local ok, cmds = pcall(api.nvim_buf_get_commands, bufnr, { builtin = false })
  if not ok then cmds = {} end
  if cmds["MDTableWrap"] then return end

  local mdtable = require("markdown.commands.mdtable")

  composer.verb("MDTableWrap", {
    buffer = bufnr,
    desc = "[markdown.nvim] Wrap the table at the cursor (or every table, off any) to the resolved width plan",
    routes = { { path = {}, run = function() mdtable.wrap_at_cursor(bufnr) end } },
  })

  composer.verb("MDTableUnwrap", {
    buffer = bufnr,
    desc = "[markdown.nvim] Merge continuation rows of the table at the cursor back into one row each",
    routes = { { path = {}, run = function() mdtable.unwrap_at_cursor(bufnr) end } },
  })

  composer.verb("MDTableWrapVisual", {
    buffer = bufnr,
    bang = true,
    range = true,
    desc = "[markdown.nvim] Wrap tables in the visual selection; ! unwraps first for a clean recompute",
    routes = {
      {
        path = {},
        range = true,
        run = function(ctx) mdtable.wrap_visual(bufnr, ctx.range.line1, ctx.range.line2, ctx.bang) end,
      },
    },
  })

  composer.verb("MDTableWrapVisible", {
    buffer = bufnr,
    bang = true,
    desc = "[markdown.nvim] Wrap tables intersecting the visible window range; ! unwraps first",
    routes = { { path = {}, run = function(ctx) mdtable.wrap_visible(bufnr, ctx.bang) end } },

function M.run(argv)
  argv = argv or {}
  local sub = argv[1] or "pdf"
  local fn = subcommands[sub]
  if not fn then
    notify.warn("export: unknown subcommand '" .. sub .. "' (supported: pdf)")
    return
  end
  fn(argv[2])
end

function M.run(argv)
  argv = argv or {}
  local sub = argv[1] or "paste"
  local fn = subcommands[sub]
  if not fn then
    notify.warn("image: unknown subcommand '" .. sub .. "' (supported: paste, screenshot)")
    return
  end
  fn()
end

function M.from_buffer(bufnr)
  bufnr = bufnr or api.nvim_get_current_buf()
  local lines = api.nvim_buf_get_lines(bufnr, 0, -1, false)
  return M.from_lines(lines)
end

local function configured_style()
  local ok, config = pcall(require, "markdown.config")
  if not ok then return {} end
  local toc = config.get().toc or {}
  return { style = toc.anchor_style, separator = toc.anchor_separator }
end

local function get_cfg()
  local ok, config = pcall(require, "markdown.config")
  local t = (ok and config.get().table) or {}
  return {
    header_align = t.header_align or "center",
    entry_align = t.entry_align or "center",
    col_overrides = t.col_overrides,
  }
end

function M.on(event, fn)
  M._hooks[event] = M._hooks[event] or {}
  table.insert(M._hooks[event], fn)
end

local function reselect_visual(row, scol, ecol)
  fn.setpos("'<", { 0, row + 1, scol + 1, 0 })
  fn.setpos("'>", { 0, row + 1, ecol + 1, 0 })
  local reselect = api.nvim_replace_termcodes("<Esc>gv", true, false, true)
  api.nvim_feedkeys(reselect, "nx", false)
end

function M.is_file_line(line)
  local target = extract_file_target_from_line(line)
  if not target then return false end
  return not is_url(target)
end

local function theme_marker_fg()
  return pick_group_fg({ "@markup.quote.markdown", "@text.quote", "Comment" }, "#6A9955")
end

local function theme_text_fg()
  return pick_group_fg({ "@markup.quote.markdown", "@text.quote", "String" }, "#7EE787")
end

function M.apply(opts)
  opts = opts or {}
  set_hl(opts.blockquote_hl or {})
  ensure_decoration_provider()
end

function M.items(opts)
  opts = opts or {}
  local cfg = require("markdown.config").get()
  local mcfg = cfg.menu or {}
  if mcfg.enable == false then return {} end

  local actions = require("markdown.bindings.actions")
  local items = {}

  -- Fold controls — only meaningful on a heading (or when forced).
  if mcfg.fold ~= false and (opts.force_fold or on_heading()) then
    items[#items + 1] = { name = "Fold / Unfold Heading", cmd = actions.fold_toggle, rtxt = "za" }
    items[#items + 1] = { name = "Fold below H2 (toggle)", cmd = actions.fold_h2plus, rtxt = "zk" }
    items[#items + 1] = { name = "Unfold All", cmd = actions.unfold_all, rtxt = "zu" }
  end

  -- Document-level actions (always available in a markdown buffer).
  local doc = {}
  if mcfg.toc ~= false then
    doc[#doc + 1] = { name = "Insert / Refresh TOC", cmd = actions.toc, rtxt = "<leader>toc" }
  end
  if mcfg.refs ~= false then
    doc[#doc + 1] = {
      name = "Sync References",
      cmd = function() require("markdown.core.refs").reconcile() end,
    }
  end

  if #items > 0 and #doc > 0 then items[#items + 1] = { name = "separator" } end
  vim.list_extend(items, doc)

  return items
end

function M.submenu(label)
  local items = M.items()
  if #items == 0 then return nil end
  return { name = label or "  Markdown", hl = "Exblue", items = items }
end

function M.op_enabled(op)
  if not M.enabled() then return false end
  local c = cfg().fenced_scope or {}
  local ops = c.operations or {}
  return ops[op] ~= false
end

function M.toggle()
  M.set_enabled(not M.enabled())
  return M.enabled()
end

local function build_html(chosen, source)
  local buf = {}
  local function w(s) table.insert(buf, s) end

  w(
    "<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
  )
  w("<title>TableView — Preview</title>")
  w([[<style>
    :root{--bg:#f7fafc;--card:#ffffff;--muted:#6b7280;--border:#c4c7cc;--accent:#0f172a;--header-bg:#0f172a;--header-fg:#ffffff;--zebra:#fbfdff;}
    html,body{height:100%;margin:0;background:var(--bg);font-family:Inter,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--accent);}
    .wrap{max-width:1100px;margin:36px auto;padding:18px;}
    .card{background:var(--card);border-radius:10px;box-shadow:0 6px 24px rgba(15,23,42,0.08);overflow:hidden;border:2px solid var(--border);}
    header{padding:14px 18px;border-bottom:1px solid rgba(0,0,0,0.04);display:flex;align-items:center;gap:12px;}
    header h1{font-size:16px;margin:0;font-weight:600;color:var(--header-bg);}
    header .meta{margin-left:auto;font-size:12px;color:var(--muted);}
    .table-wrap{padding:18px;overflow:auto;}
    table{width:100%;border-collapse:separate;border-spacing:0;table-layout:auto;}
    thead th{background:linear-gradient(180deg,var(--header-bg),rgba(0,0,0,0.03));color:var(--header-fg);padding:10px 12px;text-align:left;font-weight:700;border-bottom:3px solid var(--border);font-size:13px;}
    tbody td{padding:10px 12px;border-bottom:1px solid rgba(0,0,0,0.04);vertical-align:top;font-size:13px}
    tbody tr:nth-child(odd){background:var(--zebra)}
    tbody tr:hover{background:rgba(15,23,42,0.03)}
    .caption{padding:12px 18px;border-top:1px solid rgba(0,0,0,0.04);font-size:12px;color:var(--muted);}
  </style>]])
  w("</head><body><div class='wrap'><div class='card'>")
  w("<header><h1>Table Preview</h1>")
  if source and source ~= "" then w("<div class='meta'>" .. html_escape(source) .. "</div>") end
  w("</header>")
  w("<div class='table-wrap'><table><thead><tr>")
  for _, c in ipairs(chosen.header.cells) do
    w("<th>" .. html_escape(c.content or "") .. "</th>")
  end
  w("</tr></thead><tbody>")
  for _, r in ipairs(chosen.rows) do
    w("<tr>")
    for _, c in ipairs(r.cells) do
      w("<td>" .. html_escape(c.content or "") .. "</td>")
    end
    w("</tr>")
  end

local function select_builtin(items, opts, format, on_choose)
  vim.ui.select(items, {
    prompt = opts.prompt or "Select",
    format_item = format,
  }, function(choice)
    if choice then on_choose(choice) end
  end)
end
